#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// scripts/check-secret-presence.mjs — generated by arbiter (anti-fake-green, INV-89).
//
// Fail-loud secret-presence guard. A CI step that depends on a secret which is EMPTY must FAIL
// loudly — never silently skip and report green. The classic fake-green:
//   [ -z "$SECRET" ] && { echo "no secret — skip"; exit 0; }   # green, work never done
// This guard scans .github/workflows run-steps for that silent-skip-on-empty-secret idiom: an
// emptiness test on a secret-backed env/assignment var that reaches `exit 0` WITHOUT an explicit
// `vars.SKIP_<NAME>` opt-out. The ONLY sanctioned skip is an explicit SKIP_<NAME>=true; otherwise
// the empty-secret branch must `exit 1` loud:
//   test -n "$SECRET" || { [ "${SKIP_X}" = "true" ] && exit 0 || { echo "::error::..."; exit 1; }; }
// secrets.GITHUB_TOKEN (always auto-provided) and informational workflows
// (heartbeat/nightly/weekly/monthly/notify) are exempt. NO-DATA (no secret steps) is a PASS.
//
// Usage: node scripts/check-secret-presence.mjs [--dir <path>] [--help]
// Exit codes (INV-53): 0=PASS, 1=FAIL (unguarded secret-skip), 2=ERROR (self).
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { join, resolve, basename } from 'node:path'

const args = process.argv.slice(2)
if (args.includes('--help') || args.includes('-h')) {
  process.stdout.write(
    [
      'Usage: node scripts/check-secret-presence.mjs [--dir <path>]',
      '',
      'Fails when a workflow run-step tests a secret-backed variable for emptiness and then',
      '`exit 0` (silent skip) without an explicit `vars.SKIP_<NAME>` opt-out — a fake-green where',
      'a missing secret turns a gate green with the real work never done. GITHUB_TOKEN and',
      'informational workflows (heartbeat/nightly/weekly/monthly/notify) are exempt.',
      'NO-DATA (no workflows or no secret-dependent steps) is a PASS.',
      '',
    ].join('\n') + '\n',
  )
  process.exit(0)
}

const dirArg = args.indexOf('--dir')
const ROOT = dirArg >= 0 && args[dirArg + 1] ? resolve(args[dirArg + 1]) : process.cwd()

const INFORMATIONAL_PATTERNS = ['heartbeat', 'nightly', 'weekly', 'monthly', 'notify']
const ALWAYS_PRESENT_SECRET = 'GITHUB_TOKEN'

function collectYamlFiles(dir) {
  if (!existsSync(dir)) return []
  const out = []
  let entries
  try {
    entries = readdirSync(dir, { withFileTypes: true })
  } catch {
    return out
  }
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue
    const full = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...collectYamlFiles(full))
    else if (entry.isFile() && (entry.name.endsWith('.yml') || entry.name.endsWith('.yaml')))
      out.push(full)
  }
  return out
}

function extractSteps(content) {
  const lines = content.split('\n')
  const steps = []
  let cur = null
  let inSteps = false
  let stepsIndent = null
  let stepDashIndent = null
  const flush = () => {
    if (cur) steps.push(cur.join('\n'))
    cur = null
  }
  for (const line of lines) {
    if (line.trim() === '') {
      if (cur) cur.push(line)
      continue
    }
    const indent = line.length - line.trimStart().length
    const stepsKey = /^(\s*)steps:\s*$/.exec(line)
    if (stepsKey) {
      flush()
      inSteps = true
      stepsIndent = stepsKey[1].length
      stepDashIndent = null
      continue
    }
    if (!inSteps) continue
    if (indent <= stepsIndent && /^\s*[\w-]+:(\s|$)/.test(line)) {
      flush()
      inSteps = false
      continue
    }
    const dash = /^(\s*)-\s/.exec(line)
    if (dash && (stepDashIndent === null || dash[1].length === stepDashIndent)) {
      stepDashIndent = dash[1].length
      flush()
      cur = [line]
      continue
    }
    if (cur) cur.push(line)
  }
  flush()
  return steps
}

function analyzeStep(rawStepText) {
  // Strip comments first so a commented-out opt-out (`# SKIP_FAKE=true`) cannot satisfy the guard
  // and a commented `exit 0` is not treated as a real skip.
  const stepText = rawStepText
    .split('\n')
    .map((l) => l.replace(/(^|\s)#.*$/, '$1'))
    .join('\n')
  const secretVars = new Set()
  const reBind = /([A-Za-z_][A-Za-z0-9_]*)\s*[:=]\s*"?\$\{\{\s*secrets\.([A-Za-z0-9_]+)\s*\}\}/g
  let m
  while ((m = reBind.exec(stepText))) {
    if (m[2] === ALWAYS_PRESENT_SECRET) continue
    secretVars.add(m[1])
  }
  const directSecretEmpty = /-[zn]\s+"?\$\{\{\s*secrets\.([A-Za-z0-9_]+)/.exec(stepText)
  const direct = directSecretEmpty && directSecretEmpty[1] !== ALWAYS_PRESENT_SECRET
  if (secretVars.size === 0 && !direct) return null
  if (!/\bexit\s+0\b/.test(stepText)) return null
  let emptyOnSecret = Boolean(direct)
  for (const v of secretVars) {
    if (new RegExp(`-[zn]\\s+"?\\$\\{?${v}\\b`).test(stepText)) {
      emptyOnSecret = true
      break
    }
  }
  if (!emptyOnSecret) return null
  // Sanctioned opt-out: a REAL `SKIP_<NAME> = true` shell comparison in the (comment-stripped) run.
  // A `vars.SKIP_<NAME>` env binding alone is NOT enough — the run must actually test it.
  const hasOptOut = /SKIP_[A-Za-z0-9_]+["}]*\s*(?:==?|!=)\s*["']?true/.test(stepText)
  if (hasOptOut) return null
  return secretVars.size > 0 ? [...secretVars].join(', ') : `secrets.${directSecretEmpty[1]}`
}

function findViolations(filePath) {
  const name = basename(filePath)
  if (INFORMATIONAL_PATTERNS.some((p) => name.includes(p))) return []
  let content
  try {
    content = readFileSync(filePath, 'utf-8')
  } catch {
    return []
  }
  const findings = []
  for (const step of extractSteps(content)) {
    const vars = analyzeStep(step)
    if (vars) {
      const stepName = /name:\s*(.+)/.exec(step)
      const label = stepName ? stepName[1].trim() : '(unnamed step)'
      findings.push(
        `${filePath}: step "${label}" skips on empty secret (${vars}) without vars.SKIP_ opt-out`,
      )
    }
  }
  return findings
}

function main() {
  const findings = []
  for (const file of collectYamlFiles(join(ROOT, '.github', 'workflows'))) {
    for (const v of findViolations(file)) findings.push(v)
  }
  if (findings.length > 0) {
    process.stderr.write(
      'check-secret-presence: FAIL — secret-dependent step silently skips on an empty secret:\n',
    )
    for (const f of findings) process.stderr.write(`    ${f}\n`)
    process.stderr.write(
      '  Fix: gate the skip behind an explicit `vars.SKIP_<NAME>=true`, otherwise fail loud:\n' +
        '    test -n "$SECRET" || { [ "${SKIP_X}" = "true" ] && exit 0 \\\n' +
        '      || { echo "::error::SECRET is empty and SKIP_X is not true"; exit 1; }; }\n',
    )
    return 1
  }
  process.stdout.write(
    'check-secret-presence: no unguarded secret-skip steps — PASS (NO-DATA when no secret steps)\n',
  )
  return 0
}

try {
  process.exit(main())
} catch (e) {
  process.stderr.write(`check-secret-presence: ERROR — ${e?.message ?? e}\n`)
  process.exit(2)
}
